n=19; g=[[0]*n for _ in range(n)]; centers={(3,6):8,(4,13):4,(12,14):1,(14,3):2}; markers=set()
for (r,c),v in centers.items():
 for dr,dc in [(0,0),(-1,0),(1,0),(0,-1),(0,1)]:
  rr,cc=r+dr,c+dc
  if dr==dc==0:g[rr][cc]=v
  else:markers.add((rr,cc));g[rr][cc]=3
for r,c in [(10,8),(9,8),(11,8),(10,7),(10,9)]:g[r][c]=3
for r in range(n):
 for c in range(n):
  if g[r][c]==0 and (r in [3,4,12,14] or c in [6,13,14,3]):
   g[r][c]=centers.get((r,c), centers.get((r,c), 0)) or (centers.get((0,c),0))
# now actual apply row color then column precedence using maps
rowcol={r:v for (r,c),v in centers.items()}; colcol={c:v for (r,c),v in centers.items()}
for r in range(n):
 for c in range(n):
  if g[r][c]==0 and (r in rowcol or c in colcol): g[r][c]=colcol.get(c,rowcol.get(r,0))
print('\n'.join(' '.join(map(str,row)) for row in g))

